={{ (() => {
  // 1. Map text sizes to numbers for easy comparison
  const sizeMap = { SMALL: 1, MEDIUM: 2, LARGE: 3 };

  // 2. Extract values into clearly named variables from the new schema
  const requestedSize = $('When Executed by Another Workflow').item.json.package_size;
  const maxLockerSize = $json.locker_package_size;
  // locker_availability contains 'LIMITED', 'FULL', etc.
  const currentStatus = $json.locker_availability; 

  const requestedScore = sizeMap[requestedSize] || 0;
  const lockerMaxScore = sizeMap[maxLockerSize] || 0;

  // RULE 1: If the package is bigger than the locker's maximum capacity, reject it
  if (lockerMaxScore < requestedScore) {
    return {
      eligible: false,
      reason: `Package size (${requestedSize}) exceeds maximum locker capacity (${maxLockerSize}).`
    };
  }

  // RULE 2: If the locker is completely full, reject it
  if (currentStatus === 'FULL') {
    return {
      eligible: false,
      reason: 'Locker capacity is completely FULL.'
    };
  }

  // RULE 3: If capacity is limited, ONLY allow SMALL packages
  if (currentStatus === 'LIMITED' && requestedSize !== 'SMALL') {
    return {
      eligible: false,
      reason: `Locker capacity is LIMITED. Cannot accept ${requestedSize} packages.`
    };
  }

  // If all rules pass, the locker is eligible
  return {
    eligible: true,
    reason: null
  };
})() }}

